solution.solution.cpp:
#include <set>
#include <sstream>
#include <string>
#include <vector>

struct Event { std::string time, process, pid, operation, path, result, detail; };
struct Summary
{
    std::vector<std::string> filesRead, filesWritten, keysRead, keysWritten, notFound;
};

std::vector<std::string> splitCsvLine(const std::string& line)
{
    std::vector<std::string> fields;
    std::string field;
    bool quoted{ false };
    for (std::size_t i{ 0 }; i < line.size(); ++i)
    {
        const char c{ line[i] };
        if (quoted)
        {
            if (c == '"' && i + 1 < line.size() && line[i + 1] == '"') { field += '"'; ++i; }
            else if (c == '"') quoted = false;
            else field += c;
        }
        else if (c == '"') quoted = true;
        else if (c == ',') { fields.push_back(field); field.clear(); }
        else if (c != '\r') field += c;
    }
    fields.push_back(field);
    return fields;
}

std::vector<Event> parseLog(const std::string& csv)
{
    std::vector<Event> events;
    std::istringstream in{ csv };
    std::string line;
    bool header{ true };
    while (std::getline(in, line))
    {
        if (line.empty() || line == "\r") continue;
        if (header) { header = false; continue; }
        const auto f{ splitCsvLine(line) };
        if (f.size() != 7) continue;
        events.push_back({ f[0], f[1], f[2], f[3], f[4], f[5], f[6] });
    }
    return events;
}

Summary summarise(const std::vector<Event>& events, const std::string& process)
{
    std::set<std::string> read, written, keysRead, keysWritten, missing;
    for (const Event& e : events)
    {
        if (e.process != process) continue;
        if (e.result == "NAME NOT FOUND") missing.insert(e.path);
        if (e.result != "SUCCESS") continue;
        if (e.operation == "ReadFile") read.insert(e.path);
        else if (e.operation == "WriteFile") written.insert(e.path);
        else if (e.operation == "RegQueryValue") keysRead.insert(e.path);
        else if (e.operation == "RegSetValue") keysWritten.insert(e.path);
    }
    return { { read.begin(), read.end() }, { written.begin(), written.end() }, { keysRead.begin(), keysRead.end() },
             { keysWritten.begin(), keysWritten.end() }, { missing.begin(), missing.end() } };
}

unitTests:
using S = std::vector<std::string>;
static const std::string LOG{
    "\"Time of Day\",\"Process Name\",\"PID\",\"Operation\",\"Path\",\"Result\",\"Detail\"\n"
    "\"10:14:02.1\",\"Inventory.exe\",\"4120\",\"CreateFile\",\"C:\\App\\plugins.ini\",\"NAME NOT FOUND\",\"Desired Access: Generic Read\"\n"
    "\"10:14:02.2\",\"Inventory.exe\",\"4120\",\"ReadFile\",\"C:\\App\\config.ini\",\"SUCCESS\",\"Offset: 0, Length: 512\"\n"
    "\"10:14:02.3\",\"Inventory.exe\",\"4120\",\"ReadFile\",\"C:\\App\\config.ini\",\"SUCCESS\",\"Offset: 512, Length: 98\"\n"
    "\"10:14:02.4\",\"Inventory.exe\",\"4120\",\"RegQueryValue\",\"HKCU\\Software\\Inventory\\Theme\",\"SUCCESS\",\"Type: REG_SZ, Data: dark\"\n"
    "\"10:14:02.5\",\"explorer.exe\",\"880\",\"ReadFile\",\"C:\\Windows\\explorer.exe\",\"SUCCESS\",\"\"\n"
    "\r\n"
    "\"10:14:05.0\",\"Inventory.exe\",\"4120\",\"WriteFile\",\"C:\\App\\Saves\\items, backup.dat\",\"SUCCESS\",\"Offset: 0\"\n"
    "\"10:14:05.1\",\"Inventory.exe\",\"4120\",\"RegSetValue\",\"HKCU\\Software\\Inventory\\LastOpened\",\"SUCCESS\",\"Data: \"\"items\"\"\"\n"
    "\"10:14:05.2\",\"Inventory.exe\",\"4120\",\"WriteFile\",\"C:\\App\\locked.dat\",\"ACCESS DENIED\",\"\"\n"
    "broken line\n" };

TEST("CSV fields") {
    CHECK_EQ(splitCsvLine("a,b,c"), (S{ "a", "b", "c" }));
    CHECK_EQ(splitCsvLine("\"x, y\",\"z\""), (S{ "x, y", "z" }));
    CHECK_EQ(splitCsvLine("\"say \"\"hi\"\"\",,end"), (S{ "say \"hi\"", "", "end" }));
    CHECK_EQ(splitCsvLine(""), (S{ "" }));
}
TEST("parsing the log") {
    const auto events{ parseLog(LOG) };
    CHECK_EQ(events.size(), 8u);
    if (events.size() != 8) return;
    CHECK_EQ(events[0].operation, std::string("CreateFile"));
    CHECK_EQ(events[5].path, std::string("C:\\App\\Saves\\items, backup.dat"));
    CHECK_EQ(events[6].detail, std::string("Data: \"items\""));
}
TEST("the summary") {
    const Summary s{ summarise(parseLog(LOG), "Inventory.exe") };
    CHECK_EQ(s.filesRead, (S{ "C:\\App\\config.ini" }));
    CHECK_EQ(s.filesWritten, (S{ "C:\\App\\Saves\\items, backup.dat" }));
    CHECK_EQ(s.keysRead, (S{ "HKCU\\Software\\Inventory\\Theme" }));
    CHECK_EQ(s.keysWritten, (S{ "HKCU\\Software\\Inventory\\LastOpened" }));
    CHECK_EQ(s.notFound, (S{ "C:\\App\\plugins.ini" }));
    CHECK(summarise(parseLog(LOG), "notepad.exe").filesRead.empty());
}

